    public void UpdatePreview()
    {
        if (_current_question == null) return;

        if (_current_question.QuestionImage != null)
        {
            _question_sprite.Texture = _current_question.QuestionImage;
            _question_sprite.Position = _current_question.QuestionPosition;
            _question_sprite.Visible = true;
        }

        List<Texture2D> _answers = new List<Texture2D>();
        _answers.Add(_current_question.CorrectAnswer);
        // 答案预览
        if (_current_question.WrongAnswerOptions != null && _current_question.WrongAnswerOptions.Length > 0)
        {
            _answers.AddRange(_current_question.WrongAnswerOptions);
        }
        _on_question_answer_sprite.Texture = _current_question.CorrectAnswer;
        _on_question_answer_sprite.Position = _current_question.OnQuestionAnswerPosition;
        _on_question_answer_sprite.Scale = new Vector2(_current_question.OnQuestionAnswerScale, _current_question.OnQuestionAnswerScale);
        _on_question_answer_sprite.Modulate = new Color(1, 1, 1, 0.6f);
        _on_question_answer_sprite.Visible = true;

        // 选项
        _UpdateOptions(_answers);

        _viewport.RenderTargetUpdateMode = SubViewport.UpdateMode.Always;
    }


    protected void _UpdateOptions(List<Texture2D> answers)
    {
        foreach (var child in _answers_container.GetChildren())
        {
            child.QueueFree();
        }


        for (int i = 0; i < answers.Count; i++)
        {
            var sprite = new Sprite2D
            {
                Texture = answers[i],
                Position = _currentQuestion.AnswerOptionPositions[i],
                Modulate = new Color(1, 1, 0.5f, 0.8f),
                Name = $"Option_{i}"
            };
            _optionsContainer.AddChild(sprite);
        }
    }

    
