[Tool]
public partial class GridDrawer: Node2D
{
    private int _gridSize = 50;
    private Color _gridColor = new Color(0.3f, 0.3f, 0.3f, 0.5f);
    private Color _majorGridColor = new Color(0.4f, 0.4f, 0.4f, 0.8f);

    public override void _Draw()
    {
        var viewportSize = new Vector2(1920, 1080);

        // 绘制小网格线（每50像素）
        for (float x = 0; x <= viewportSize.X; x += _gridSize)
        {
            DrawLine(new Vector2(x, 0), new Vector2(x, viewportSize.Y), _gridColor, 1);
        }

        for (float y = 0; y <= viewportSize.Y; y += _gridSize)
        {
            DrawLine(new Vector2(0, y), new Vector2(viewportSize.X, y), _gridColor, 1);
        }

        // 绘制主网格线（每200像素）
        for (float x = 0; x <= viewportSize.X; x += _gridSize * 4)
        {
            DrawLine(new Vector2(x, 0), new Vector2(x, viewportSize.Y), _majorGridColor, 2);
        }

        for (float y = 0; y <= viewportSize.Y; y += _gridSize * 4)
        {
            DrawLine(new Vector2(0, y), new Vector2(viewportSize.X, y), _majorGridColor, 2);
        }
    }
}

